// Speaking Samples — topic catalog
// Each category contains 40+ topics. Both Academic & General IELTS Speaking
// share the same questions, so this single source feeds both flows.
// Topic id is auto-generated as a URL-safe slug from the label.

export type SpeakingTopic = {
  id: string;
  label: string;
};

const slugify = (s: string): string =>
  s
    .toLowerCase()
    .replace(/&/g, " and ")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");

const make = (labels: string[]): SpeakingTopic[] => {
  const seen = new Set<string>();
  return labels.map((label) => {
    let id = slugify(label);
    let n = 2;
    while (seen.has(id)) id = `${slugify(label)}-${n++}`;
    seen.add(id);
    return { id, label };
  });
};

